                placeholder="Ex: João Silva"
                value={formData.name}
                onChange={handleChange}
              />
            </div>

            <div>
              <label htmlFor="phone" className="block text-sm font-medium text-slate-700 mb-1">WhatsApp</label>
              <input
                type="tel"
                id="phone"
