        <div className="text-center max-w-3xl mx-auto mb-16">
          <span className="text-brand-600 font-bold tracking-wider uppercase text-sm mb-2 block">Investimento Inteligente</span>
          <h2 className="text-3xl md:text-5xl font-extrabold text-slate-900 mb-6 tracking-tight">
            Escolha o plano ideal para você
          </h2>
          <p className="text-lg text-slate-500">
            Valores referentes à licença anual por usuário. <br className="hidden md:inline" /> Parcelamento em até 12x no cartão.
          </p>
        </div>

        {/* Plans Grid */}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 items-end max-w-7xl mx-auto">
          {plans.map((plan) => (
            <div 
              key={plan.id}
              className={`flex flex-col relative bg-white rounded-3xl transition-all duration-300 ${plan.isHighlight ? 'shadow-2xl shadow-brand-900/20 lg:-mt-12 z-10 ring-4 ring-brand-500/10' : 'shadow-lg hover:shadow-xl mt-0 z-0 border'} ${plan.borderColor}`}
            >
              {/* Highlight Header */}
              {plan.isHighlight && (
                <div className="bg-gradient-to-r from-brand-600 to-indigo-600 text-white text-center py-4 rounded-t-2xl font-bold text-sm uppercase tracking-widest flex items-center justify-center gap-2">
                  <Star size={16} fill="white" /> {plan.badge} <Star size={16} fill="white" />
                </div>
              )}

              <div className={`p-6 md:p-8 ${!plan.isHighlight ? 'rounded-3xl' : 'rounded-b-3xl'} flex flex-col h-full`}>

                {/* Plan Name & Icon */}
                <div className="flex flex-col items-center justify-center mb-8 text-center min-h-[160px]">
                  {plan.icon}
                  <h3 className="text-2xl font-bold text-slate-900 mb-1">{plan.name}</h3>
                  <div className="flex items-baseline justify-center gap-1">
                      <span className="text-sm text-slate-400 font-medium">R$</span>
                      <span className="text-4xl font-extrabold text-slate-900 tracking-tight">{plan.price}</span>
                      <span className="text-sm text-slate-400 font-medium">/ano</span>
                  </div>
                </div>

                {/* Features List */}
                <div className="space-y-4 mb-10 flex-1">
                  {featuresList.map((feature, idx) => {
                    const { content, checkColor } = getFeatureDisplay(feature, plan.id);
                    return (
                        <div key={idx} className="flex items-start text-left group">
                        <div className="mr-3 mt-0.5 min-w-[18px]">
                            <Check className={`w-5 h-5 ${checkColor}`} strokeWidth={3} />
                        </div>
                        <div className="leading-snug">
                            {content}
                        </div>
                        </div>
                    );
                  })}
