                        className={`h-14 text-base ${plan.isHighlight ? 'bg-brand-600 hover:bg-brand-700 shadow-xl shadow-brand-500/30' : 'border-slate-300 text-slate-600 hover:border-brand-600 hover:text-brand-600'}`}
