        var elemPrincipal = document.querySelector("#planoouro_valor_principal");
        var elemParcela = document.querySelector("#planoouro_valor_parcela");
        var elemDesconto = document.querySelector("#planoouro_valor_principal_desconto");

        if (elemPrincipal) elemPrincipal.textContent = preco.precoRegular;
        if (elemParcela) elemParcela.textContent = preco.precoParcela;
        if (elemDesconto) elemDesconto.textContent = preco.precoAVista;
    }
    function executarRedirecionamento() {
        var temp = sessionStorage.getItem('waspeed_compra_temp');
        if (!temp) return;
        var info = JSON.parse(temp);
        if (info.plano !== 'ouro') return;

        sessionStorage.removeItem('waspeed_compra_temp');
        var quantidade = info.quantidade;
        var dados = info.dadosCliente;

        var linkBase = linksOuro[quantidade];
        if (!linkBase) return;

        var urlFinal = linkBase.link +
            'name=' + encodeURIComponent(dados.name) +
            '&email=' + encodeURIComponent(dados.email) +
            '&phone=' + encodeURIComponent(dados.phone);

        if (dados.sck) {
            urlFinal += '&sck=' + encodeURIComponent(dados.sck);
        }

        if (dados.utm_source) urlFinal += '&utm_source=' + encodeURIComponent(dados.utm_source);
        if (dados.utm_medium) urlFinal += '&utm_medium=' + encodeURIComponent(dados.utm_medium);
        if (dados.utm_campaign) urlFinal += '&utm_campaign=' + encodeURIComponent(dados.utm_campaign);
        if (dados.utm_content) urlFinal += '&utm_content=' + encodeURIComponent(dados.utm_content);
        if (dados.utm_term) urlFinal += '&utm_term=' + encodeURIComponent(dados.utm_term);

        if (dados.gclid) urlFinal += '&gclid=' + encodeURIComponent(dados.gclid);
        if (dados.gad_source) urlFinal += '&gad_source=' + encodeURIComponent(dados.gad_source);
        if (dados.gad_campaignid) urlFinal += '&gad_campaignid=' + encodeURIComponent(dados.gad_campaignid);
        if (dados.gbraid) urlFinal += '&gbraid=' + encodeURIComponent(dados.gbraid);

        if (dados.lead) urlFinal += '&lead=' + encodeURIComponent(dados.lead);

        setTimeout(function() {
            window.location.href = urlFinal;
        }, 1000);
    }
    function inicializarBotoes() {
        var quantidadeInput = document.querySelector("#planoouro_quantidade_licencas");
        var btnMenos = document.querySelector("#planoouro_btn_menos");
        var btnMais = document.querySelector("#planoouro_btn_mais");
        if (!quantidadeInput || !btnMenos || !btnMais) {
            setTimeout(inicializarBotoes, 100);
            return;
        }
        btnMenos.onclick = function(e) {
            e.preventDefault();
            var q = parseInt(quantidadeInput.value) || 1;
            if (q > 1) {
                quantidadeInput.value = q - 1;
                atualizarPreco();
            }
        };
        btnMais.onclick = function(e) {
            e.preventDefault();
            var q = parseInt(quantidadeInput.value) || 1;
            if (q < 10) {
                quantidadeInput.value = q + 1;
                atualizarPreco();
            }
        };
        quantidadeInput.value = "1";
        atualizarPreco();
    }
    function inicializarFormulario() {
        var botaoCompra = document.querySelector("#planoouro");

        if (!botaoCompra) {
            setTimeout(inicializarFormulario, 100);
            return;
        }
        botaoCompra.addEventListener('click', function(e) {
            var dados = coletarDadosFormulario();
            if (!validarCamposObrigatorios(dados)) {
                e.preventDefault();
                e.stopPropagation();
                return false;
            }
            var quantidadeInput = document.querySelector("#planoouro_quantidade_licencas");
            var quantidade = parseInt(quantidadeInput.value) || 1;
            sessionStorage.setItem('waspeed_compra_temp', JSON.stringify({
                quantidade: quantidade,
                dadosCliente: dados,
                plano: 'ouro'
            }));
        }, true);
    }
    function monitorarSucesso() {
        var observer = new MutationObserver(function(mutations) {
            mutations.forEach(function(mutation) {
                mutation.addedNodes.forEach(function(node) {
                    if (node.nodeType === 1) {
                        if (node.classList && node.classList.contains('elementor-message-success')) {
                            executarRedirecionamento();
                        } else if (node.querySelector && node.querySelector('.elementor-message-success')) {
                            executarRedirecionamento();
                        }
                    }
                });
            });
        });
        observer.observe(document.body, {
            childList: true,
            subtree: true
        });

        setInterval(function() {
            if (document.querySelector('.elementor-message-success')) {
                executarRedirecionamento();
            }
        }, 500);
    }
    function iniciar() {
        inicializarBotoes();
        inicializarFormulario();
        monitorarSucesso();
    }
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', iniciar);
    } else {
        iniciar();
    }
    if (typeof jQuery !== 'undefined') {
        jQuery(document).on('elementor/popup/show', function() {
            setTimeout(iniciar, 300);
        });
    }
})();
</script>

